const shuffle=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const esc=s=>s.replace(/&/g,"&amp;").replace(/</g,"&lt;");
const isMastered=q=>qs(q.id).b>=MASTER;

function catStats(){
  const out={};
  for(const k in CATS){out[k]={total:0,mastered:0,learning:0,weak:0,acc:null,n:0,ok:0};}
  Q.forEach(q=>{const s=qs(q.id),o=out[q.cat];o.total++;o.n+=s.n;o.ok+=s.ok;
    if(s.b>=MASTER)o.mastered++;else if(s.n>0&&s.b>=2)o.learning++;else if(s.n>0)o.weak++;});
  for(const k in out){const o=out[k];o.acc=o.n?o.ok/o.n:null;o.pct=Math.round(100*o.mastered/o.total);}
  return out;
}

// вес выбора: чем ниже ящик и хуже категория — тем чаще
function pickNext(pool,exclude){
  const cst=catStats();
  const now=Date.now();
  let items=pool.filter(q=>!exclude.has(q.id)&&!isMastered(q));
  if(!items.length)return null;
  const weights=items.map(q=>{
    const s=qs(q.id);
    let w=Math.pow(MASTER+1-s.b,2);            // 36 для нового, 1 для ящика 5
    const c=cst[q.cat]; if(c.acc!==null&&c.acc<0.7)w*=1.6;   // слабая категория
    if(s.w>s.ok)w*=1.5;                         // чаще ошибался
    const ageH=(now-s.last)/36e5; if(s.last&&ageH<0.05)w*=0.2; // только что видел
    return w;
  });
  let r=Math.random()*weights.reduce((a,b)=>a+b,0);
  for(let i=0;i<items.length;i++){r-=weights[i];if(r<=0)return items[i];}
  return items[items.length-1];
}

